/// The gallery's example of `FavoriteToggle`, with its settings taken from the story.
#[allow(unused_variables, unused_mut, clippy::redundant_clone, clippy::let_and_return, clippy::clone_on_copy)]
fn render(args: &Args) -> AnyView {
    Box::new({
        let arg_label = args.text("label");
        let arg_size = args.number("size") as f32;
        let arg_star = args.bool("star");

        let (heart, star) = (State::new(true), State::new(false));
        HStack::new((
            {
                let mut it = FavoriteToggle::new(heart.binding());
                it = it.label(arg_label.clone());
                it = it.size(arg_size);
                if arg_star {
                    it = it.star();
                }
                it
            },
            FavoriteToggle::new(star.binding()).label("Pinned").star(),
        ))
        .spacing(8.0)
    })
}

impl ComponentBook for FavoriteToggle {
    fn book() -> Meta {
        Meta::new("Actions and inputs/FavoriteToggle", render)
            .summary("Heart or star that marks a favorite: filled when on.")
            .arg(ArgType::text("label", "Warm portrait"))
            .arg(ArgType::number("size", 16.0, 0.0, 64.0, 1.0))
            .arg(ArgType::bool("star", false))
            .story("Example", Args::new())
    }
}
